import heapq

class BusBookingSystem:
    def __init__(self, rows: int, seats_per_row: int):
        self.rows = rows
        self.seats_per_row = seats_per_row
        self.available = [i for i in range(1, rows * seats_per_row + 1)]
        heapq.heapify(self.available)
        self.booked = set()

    def book(self) -> int:
        if not self.available:
            return -1
        seat = heapq.heappop(self.available)
        self.booked.add(seat)
        return seat

    def cancel(self, seat_id: int) -> bool:
        if seat_id in self.booked:
            self.booked.remove(seat_id)
            heapq.heappush(self.available, seat_id)
            return True
        return False

    def is_available(self, seat_id: int) -> bool:
        return 1 <= seat_id <= self.rows * self.seats_per_row and seat_id not in self.booked

#include <queue>
#include <unordered_set>

class BusBookingSystem {
    int total;
    std::priority_queue<int, std::vector<int>, std::greater<int>> available;
    std::unordered_set<int> booked;
public:
    BusBookingSystem(int rows, int seats_per_row) {
        total = rows * seats_per_row;
        for (int i = 1; i <= total; ++i) {
            available.push(i);
        }
    }

    int book() {
        if (available.empty()) return -1;
        int seat = available.top();
        available.pop();
        booked.insert(seat);
        return seat;
    }

    bool cancel(int seat_id) {
        if (booked.count(seat_id)) {
            booked.erase(seat_id);
            available.push(seat_id);
            return true;
        }
        return false;
    }

    bool is_available(int seat_id) {
        return seat_id >= 1 && seat_id <= total && !booked.count(seat_id);
    }
};

import java.util.*;

class BusBookingSystem {
    private int total;
    private PriorityQueue<Integer> available;
    private Set<Integer> booked;

    public BusBookingSystem(int rows, int seatsPerRow) {
        this.total = rows * seatsPerRow;
        this.available = new PriorityQueue<>();
        for (int i = 1; i <= total; i++) available.offer(i);
        this.booked = new HashSet<>();
    }

    public int book() {
        if (available.isEmpty()) return -1;
        int seat = available.poll();
        booked.add(seat);
        return seat;
    }

    public boolean cancel(int seatId) {
        if (booked.contains(seatId)) {
            booked.remove(seatId);
            available.offer(seatId);
            return true;
        }
        return false;
    }

    public boolean is_available(int seatId) {
        return seatId >= 1 && seatId <= total && !booked.contains(seatId);
    }
}

class BusBookingSystem {
    constructor(rows, seatsPerRow) {
        this.total = rows * seatsPerRow;
        this.available = [];
        for (let i = 1; i <= this.total; i++) this.available.push(i);
        this.booked = new Set();
    }

    book() {
        if (this.available.length === 0) return -1;
        const seat = this.available.shift();
        this.booked.add(seat);
        return seat;
    }

    cancel(seatId) {
        if (this.booked.has(seatId)) {
            this.booked.delete(seatId);
            this.available.push(seatId);
            this.available.sort((a, b) => a - b);
            return true;
        }
        return false;
    }

    is_available(seatId) {
        return seatId >= 1 && seatId <= this.total && !this.booked.has(seatId);
    }
}
